mapper.select:
with test_method as ( select a.item_cd , STUFF(( SELECT ',' + test_item FROM tmp_test_type_method b WHERE b.item_cd = a.item_cd FOR XML PATH('') ),1,1,'') AS test_item_join , min(a.test_item) as test_item ,COUNT(*) as cnt from tmp_test_type_method a group by item_cd ), test_item_method as ( select A.item_cd, A.item_type_cd, (select code_nm from tb_common_code where com_type_cd = 'ITEM_TYPE_CD' and A.item_type_cd = code ) as item_type_name, A.item_name, case when B.cnt > 0 then 'Y' else 'N' end as reg_yn, B.test_item_join, concat(B.test_item, case when B.cnt > 1 then concat(' 외',B.cnt - 1 ,'건') else '' end ) as test_item from tb_item_mst A left outer join test_method B on A.item_cd = B.item_cd where item_type_cd is not null ) select * from test_item_method a where 1=1
AND a.item_type_cd = #{itemTypeCd}
AND a.item_cd = #{itemCd}
AND a.item_name LIKE '%' + dbo.fn_LikeEscape(#{itemName}) + '%'
and a.reg_yn = #{regYn}
order by a.item_cd

mapper.update:
update tmp_test_type_method
set    test_item   = #{testItem}
      ,test_method = #{testMethod}
      ,test_spec   = #{testSpec}
      ,test_result = #{testResult}
      ,order_dist  = #{orderDist}
      ,upd_id      = #{userId}
      ,upd_dt      = getdate()
where  test_type_method_id = #{testTypeMethodId}
